using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates multi-tile decoding on two real AV1/IVF clips. The first is 192x128 (three 64x64
/// superblock columns) split into 2x2 tiles of unequal width (two superblocks plus one), with global
/// and local warped motion enabled; the second is 128x128 split into two tile columns with OBMC
/// enabled. Every tile decodes with its own symbol decoder and CDF adaptation from the frame-initial
/// state, availability resets at each tile's top and left edges, and the post filters then run
/// frame-wide. Every decoded frame's planes must be exactly equal to dav1d's decoded output.
/// </summary>
public class Av1MultiTileDecodeTests
{
    private const string TwoByTwoClipIvfBase64 =
        "";

    private const string TwoColumnClipIvfBase64 =
        "";

    private static readonly string[] TwoByTwoLumaBase64 = [
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] TwoByTwoUBase64 = [
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] TwoByTwoVBase64 = [
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] TwoColumnLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] TwoColumnUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] TwoColumnVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    [Fact]
    public void DecodeAllFrames_TwoByTwoTiles_MatchesDav1dExactly()
        => DecodeAndCompare(TwoByTwoClipIvfBase64, TwoByTwoLumaBase64, TwoByTwoUBase64, TwoByTwoVBase64, 4);

    [Fact]
    public void DecodeAllFrames_TwoTileColumns_MatchesDav1dExactly()
        => DecodeAndCompare(TwoColumnClipIvfBase64, TwoColumnLumaBase64, TwoColumnUBase64, TwoColumnVBase64, 6);

    private static void DecodeAndCompare(string ivfBase64, string[] lumaBase64, string[] uBase64, string[] vBase64, int frameCount)
    {
        using MemoryStream stream = new(Convert.FromBase64String(ivfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(frameCount, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            Assert.Equal(Convert.FromBase64String(lumaBase64[i]), Crop(frames[i].Luma));
            Assert.Equal(Convert.FromBase64String(uBase64[i]), Crop(frames[i].ChromaU));
            Assert.Equal(Convert.FromBase64String(vBase64[i]), Crop(frames[i].ChromaV));
        }
    }

    private static byte[] Crop(Av1Plane plane)
    {
        byte[] result = new byte[plane.CropWidth * plane.CropHeight];
        for (int y = 0; y < plane.CropHeight; y++)
        {
            plane.Samples.AsSpan(y * plane.Width, plane.CropWidth).CopyTo(result.AsSpan(y * plane.CropWidth));
        }

        return result;
    }
}
